IF OBJECT_ID(N'dbo.attendance',N'U') IS NULL CREATE TABLE dbo.attendance(id INT IDENTITY PRIMARY KEY,technician_id INT NOT NULL REFERENCES dbo.technicians(id),attendance_date DATE NOT NULL,status VARCHAR(30) NOT NULL,check_in TIME(0) NULL,check_out TIME(0) NULL,work_hours DECIMAL(6,2) NOT NULL DEFAULT 0,overtime_hours DECIMAL(6,2) NOT NULL DEFAULT 0,overtime_approved_by INT NULL REFERENCES dbo.users(id),overtime_approved_at DATETIME2 NULL,note NVARCHAR(500) NULL,created_by INT NOT NULL REFERENCES dbo.users(id),updated_by INT NULL REFERENCES dbo.users(id),created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),CONSTRAINT UQ_attendance_technician_date UNIQUE(technician_id,attendance_date),CONSTRAINT CK_attendance_status CHECK(status IN('present','leave','unauthorized_leave','holiday','business_trip','off')));
IF OBJECT_ID(N'dbo.attendance_periods',N'U') IS NULL CREATE TABLE dbo.attendance_periods(id INT IDENTITY PRIMARY KEY,attendance_month TINYINT NOT NULL,attendance_year SMALLINT NOT NULL,is_closed BIT NOT NULL DEFAULT 0,closed_by INT NULL REFERENCES dbo.users(id),closed_at DATETIME2 NULL,reopened_by INT NULL REFERENCES dbo.users(id),reopened_at DATETIME2 NULL,CONSTRAINT UQ_attendance_period UNIQUE(attendance_month,attendance_year));
IF OBJECT_ID(N'dbo.attendance_audit_logs',N'U') IS NULL CREATE TABLE dbo.attendance_audit_logs(id BIGINT IDENTITY PRIMARY KEY,attendance_id INT NULL,technician_id INT NOT NULL,attendance_date DATE NULL,old_status VARCHAR(30) NULL,new_status VARCHAR(30) NULL,action_key VARCHAR(30) NOT NULL,actor_id INT NOT NULL REFERENCES dbo.users(id),reason NVARCHAR(500) NULL,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME());
GO
